-- Proof-only immutable copy of staged, inactive banks to correct option/prompt grammar before any promotion.
BEGIN;
SELECT pg_advisory_xact_lock(hashtextextended('ri_20261013_exception_bank_staging',0));
CREATE TEMP TABLE _ri_prompt_updates ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"assessment_key":"handover_verification_mastery_v1","item_key":"handover_extra_11","prompt":"How should the Specialist preserve inherited method recognition when no qualifying evidence establishes it?"},{"assessment_key":"handover_verification_mastery_v1","item_key":"handover_extra_12","prompt":"How should Handover handle the inherited first-step independence claim without qualifying evidence?"},{"assessment_key":"how_the_system_resolves_uncertainty_mastery_v1","item_key":"uncertainty_extra_01","prompt":"How should the Specialist record independent method recognition when only the final answer is established?"},{"assessment_key":"how_the_system_resolves_uncertainty_mastery_v1","item_key":"uncertainty_extra_02","prompt":"How should RI-OS treat independent first-step control when no qualifying observation exists?"},{"assessment_key":"how_the_system_resolves_uncertainty_mastery_v1","item_key":"uncertainty_extra_06","prompt":"How should the Specialist treat timed independence when a worked mathematical solution was consulted?"},{"assessment_key":"how_to_diagnose_mastery_v1","item_key":"how_to_diagnose_extra_19","prompt":"How should RI-OS handle the unresolved diagnostic question when evidence is not sufficient?"},{"assessment_key":"how_to_interpret_prompts_mastery_v1","item_key":"interpret_prompts_extra_19","prompt":"How should the Specialist complete the observation record when a field has no qualifying evidence?"},{"assessment_key":"how_to_interpret_prompts_mastery_v1","item_key":"interpret_prompts_extra_25","prompt":"How should the Specialist record independent first-step control when the evidence does not establish it?"},{"assessment_key":"how_to_interpret_prompts_mastery_v1","item_key":"interpret_prompts_extra_26","prompt":"How should the Specialist record a verbal-explanation claim without qualifying direct evidence?"},{"assessment_key":"logging_system_mastery_v1","item_key":"v2r8_logging_system_08","prompt":"How should the Specialist handle an unresolved prerequisite when RI-OS requires a targeted check?"},{"assessment_key":"logging_system_mastery_v1","item_key":"v2r8_logging_system_13","prompt":"How should the Specialist record independent execution when a worked solution is consulted during the middle steps?"},{"assessment_key":"operating_system_retrieval_v2","item_key":"osr_errors_01","prompt":"How should the Specialist preserve an unestablished evidence field without adding unauthorized leading prompts?"},{"assessment_key":"operating_system_retrieval_v2","item_key":"osr_logging_03","prompt":"How should the Specialist treat a required dimension without qualifying evidence while other dimensions are strong?"},{"assessment_key":"operating_system_transfer_v2","item_key":"ost_errors_01","prompt":"How should the Specialist preserve integrity when an independent step remains unestablished but a later explanation is available?"},{"assessment_key":"operating_system_transfer_v2","item_key":"ost_handover_01","prompt":"How should Handover treat independent execution when a worked solution is visible during the middle steps?"},{"assessment_key":"operating_system_transfer_v2","item_key":"ost_logging_02","prompt":"How should the Specialist record a challenging response where a visible worked example supplies the next step?"},{"assessment_key":"operating_system_transfer_v2","item_key":"ost_prompts_03","prompt":"How should the Specialist handle an observation field unsupported by the prescribed opportunity?"},{"assessment_key":"operating_system_transfer_v2","item_key":"ost_uncertainty_01","prompt":"How should Handover treat independent method continuation after the student consults a visible worked example?"},{"assessment_key":"what_not_to_do_mastery_v1","item_key":"what_not_to_do_extra_07","prompt":"How should the Specialist maintain the Handover evidence boundary when considering an unauthorized leading method question?"}]'::jsonb) AS p(assessment_key text,item_key text,prompt text);
CREATE TEMP TABLE _ri_prompt_source ON COMMIT DROP AS SELECT c.assessment_key,max(c.bank_version)::integer AS from_version,(max(c.bank_version)+1)::integer AS to_version FROM private.specialist_capability_assessment_configs c WHERE c.assessment_key IN(SELECT DISTINCT assessment_key FROM _ri_prompt_updates) GROUP BY c.assessment_key;
DO $$ BEGIN IF (SELECT COUNT(*) FROM _ri_prompt_updates)<>19 THEN RAISE EXCEPTION 'Correction count mismatch'; END IF;
IF (SELECT COUNT(*) FROM _ri_prompt_source)<>8 THEN RAISE EXCEPTION 'Bank coverage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM _ri_prompt_source b JOIN private.specialist_capability_assessment_configs c ON c.assessment_key=b.assessment_key AND c.bank_version=b.from_version WHERE c.active OR c.review_mode) THEN RAISE EXCEPTION 'Source version unexpectedly active or review'; END IF;
IF EXISTS (SELECT 1 FROM public.specialist_capability_assessment_attempts a JOIN _ri_prompt_source b ON b.assessment_key=a.assessment_key AND b.from_version=a.bank_version) THEN RAISE EXCEPTION 'Staged source has real attempts'; END IF;
IF EXISTS (SELECT 1 FROM _ri_prompt_updates p LEFT JOIN _ri_prompt_source b ON b.assessment_key=p.assessment_key LEFT JOIN private.specialist_capability_assessment_items i ON i.assessment_key=p.assessment_key AND i.item_key=p.item_key AND i.bank_version=b.from_version WHERE i.item_key IS NULL) THEN RAISE EXCEPTION 'Correction item not in staged bank'; END IF;
END $$;
INSERT INTO private.specialist_capability_assessment_configs(assessment_key,bank_version,title,assessment_deep_dive_key,evidence_kind,pass_threshold_percent,form_size,max_attempts,retry_cooldown_hours,competency_blueprint,active,created_at,retired_at,review_mode)
SELECT c.assessment_key,b.to_version,c.title,c.assessment_deep_dive_key,c.evidence_kind,c.pass_threshold_percent,c.form_size,c.max_attempts,c.retry_cooldown_hours,c.competency_blueprint,false,NOW(),NULL,false FROM private.specialist_capability_assessment_configs c JOIN _ri_prompt_source b ON b.assessment_key=c.assessment_key AND b.from_version=c.bank_version;
INSERT INTO private.specialist_capability_assessment_items(assessment_key,bank_version,item_key,competency_key,deep_dive_key,prompt,question_kind,options,correct_option_keys,critical_fail_option_keys,critical_boundary_keys,explanation,active,created_at,option_feedback)
SELECT i.assessment_key,b.to_version,i.item_key,i.competency_key,i.deep_dive_key,COALESCE(p.prompt,i.prompt),i.question_kind,i.options,i.correct_option_keys,i.critical_fail_option_keys,i.critical_boundary_keys,i.explanation,i.active,NOW(),i.option_feedback FROM private.specialist_capability_assessment_items i JOIN _ri_prompt_source b ON b.assessment_key=i.assessment_key AND b.from_version=i.bank_version LEFT JOIN _ri_prompt_updates p ON p.assessment_key=i.assessment_key AND p.item_key=i.item_key;
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM _ri_prompt_source b JOIN (SELECT assessment_key,bank_version,count(*) AS c FROM private.specialist_capability_assessment_items GROUP BY 1,2) prior ON prior.assessment_key=b.assessment_key AND prior.bank_version=b.from_version JOIN (SELECT assessment_key,bank_version,count(*) AS c FROM private.specialist_capability_assessment_items GROUP BY 1,2) latest ON latest.assessment_key=b.assessment_key AND latest.bank_version=b.to_version WHERE prior.c<>latest.c) THEN RAISE EXCEPTION 'Count preservation failed'; END IF;
 IF EXISTS (SELECT 1 FROM _ri_prompt_updates p JOIN _ri_prompt_source b ON b.assessment_key=p.assessment_key JOIN private.specialist_capability_assessment_items i ON i.assessment_key=p.assessment_key AND i.bank_version=b.to_version AND i.item_key=p.item_key WHERE i.prompt IS DISTINCT FROM p.prompt) THEN RAISE EXCEPTION 'Edited prompts absent'; END IF;
 END $$;
COMMIT;
